package com.rpb.reservation.workforce.workmode;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
import static com.rpb.reservation.workforce.workmode.WorkModeDtos.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class WorkModeApprovalPolicyTest {
 @Test void unpunchedApprovalDependsOnDatedModeRatherThanMutableLocation(){var resolver=mock(WorkModeResolver.class);var repository=mock(WorkModeRepository.class);var tenant=UUID.randomUUID();var employee=UUID.randomUUID();var store=UUID.randomUUID();var id=UUID.randomUUID();var day=LocalDate.of(2026,10,29);when(resolver.snapshot(tenant,employee,store,day)).thenReturn(new ClockPolicy("home",id,1,new Point("Old",0d,0d,100d),UUID.randomUUID(),2),new ClockPolicy("home",id,1,new Point("New",1d,1d,100d),UUID.randomUUID(),2));var clock=new WorkModeClock(repository,resolver,Clock.systemUTC());var first=clock.approvalPolicy(tenant,employee,store,day,null);var second=clock.approvalPolicy(tenant,employee,store,day,null);assertThat(first).isEqualTo(second);assertThat(first.point()).isNull();assertThat(first.addressId()).isNull();}
 @Test void legacyApprovalSourceDoesNotGainNullPolicyFields()throws Exception{var mapper=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();var source=new com.rpb.reservation.workforce.approval.ApprovalDtos.ApprovalSource(null,null,List.of(),List.of(),List.of());assertThat(mapper.readTree(mapper.writeValueAsString(source))).isEqualTo(mapper.readTree("{\"schedule\":null,\"session\":null,\"corrections\":[],\"leaves\":[],\"calendar\":[]}"));}
 @Test void legacySessionJsonRoundTripsWithoutClockPolicy()throws Exception{var mapper=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules().disable(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);var id=UUID.randomUUID();var old="{\"id\":\""+id+"\",\"scheduleId\":\""+id+"\",\"employeeId\":\""+id+"\",\"storeId\":\""+id+"\",\"inAt\":\"2026-10-28T01:00:00Z\",\"outAt\":null,\"breakStartedAt\":null,\"breaks\":[],\"overrideBreak\":false,\"version\":1}";var session=mapper.readValue(old,com.rpb.reservation.workforce.attendance.AttendanceDtos.Session.class);assertThat(mapper.readTree(mapper.writeValueAsString(session))).isEqualTo(mapper.readTree(old));}
}
